{
  "items": [
    {
      "name": "tendsto_atTop_of_geom_le",
      "module_name": "Mathlib.Analysis.SpecificLimits.Basic",
      "kind": "theorem",
      "type": "∀ {v : ℕ → ℝ} {c : ℝ}, 0 < v 0 → 1 < c → (∀ (n : ℕ), c * v n ≤ v (n + 1)) → Filter.Tendsto v Filter.atTop Filter.atTop"
    },
    {
      "name": "Set.Unbounded",
      "module_name": "Mathlib.Order.RelClasses",
      "kind": "definition",
      "type": "{α : Type u} → (α → α → Prop) → Set α → Prop"
    },
    {
      "name": "Set.Unbounded.mono",
      "module_name": "Mathlib.Order.Bounded",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {r : α → α → Prop} {s t : Set α}, s ⊆ t → Set.Unbounded r s → Set.Unbounded r t"
    },
    {
      "name": "ExpGrowth.expGrowthInf_le_expGrowthSup",
      "module_name": "Mathlib.Analysis.Asymptotics.ExpGrowth",
      "kind": "theorem",
      "type": "∀ {u : ℕ → ENNReal}, ExpGrowth.expGrowthInf u ≤ ExpGrowth.expGrowthSup u"
    },
    {
      "name": "ExpGrowth.expGrowthSup_le_iff",
      "module_name": "Mathlib.Analysis.Asymptotics.ExpGrowth",
      "kind": "theorem",
      "type": "∀ {u : ℕ → ENNReal} {a : EReal}, ExpGrowth.expGrowthSup u ≤ a ↔ ∀ b > a, ∀ᶠ (n : ℕ) in Filter.atTop, u n ≤ (b * ↑n).exp"
    },
    {
      "name": "Frequently.le_linearGrowthSup",
      "module_name": "Mathlib.Analysis.Asymptotics.LinearGrowth",
      "kind": "theorem",
      "type": "∀ {u : ℕ → EReal} {a : EReal}, (∃ᶠ (n : ℕ) in Filter.atTop, a * ↑n ≤ u n) → a ≤ LinearGrowth.linearGrowthSup u"
    }
  ]
}
